example.code:
离线：文档 → 解析清洗 → 分块(500 token, 重叠 50) → Embedding → 向量库(+ metadata: dept, acl, version)
在线：问题 → 改写 → [向量检索 Top20 + BM25 Top20] → 权限过滤 → Rerank Top5 → Prompt → LLM → 答案+引用

Prompt 模板示例：
你是企业知识助手。只根据<资料>回答，资料中没有就回答“未找到相关资料”，并在句末标注来源编号。
<资料>
[1] {chunk1}
[2] {chunk2}
</资料>
问题：{question}

// Spring AI：按 token 切分（参数依版本可通过 builder 设置）
TokenTextSplitter splitter = TokenTextSplitter.builder()
        .withChunkSize(500)          // 目标块大小（token）
        .withMinChunkSizeChars(200)
        .build();
List<Document> chunks = splitter.apply(docs);

// 为每个块补充上下文，提升检索效果
for (Document c : chunks) {
    String title = (String) c.getMetadata().getOrDefault("title", "");
    c.getMetadata().put("section_path", title);
}

// 混合检索 + RRF 融合（示意）
List<Doc> vec  = vectorSearch(query, 20);
List<Doc> bm25 = keywordSearch(query, 20);

Map<String, Double> score = new HashMap<>();
Map<String, Doc> byId = new HashMap<>();
int k = 60;
for (List<Doc> list : List.of(vec, bm25)) {
    for (int i = 0; i < list.size(); i++) {
        Doc d = list.get(i);
        byId.put(d.id(), d);
        score.merge(d.id(), 1.0 / (k + i + 1), Double::sum);
    }
}
List<Doc> fused = score.entrySet().stream()
        .sorted(Map.Entry.<String, Double>comparingByValue().reversed())
        .limit(30).map(e -> byId.get(e.getKey())).toList();

List<Doc> top5 = reranker.rerank(query, fused, 5);   // Cross-Encoder 精排

// 计算 Hit@K 与 MRR（示意）
record Case(String question, Set<String> goldChunkIds) {}

double hit = 0, mrr = 0;
for (Case c : evalSet) {
    List<String> ids = retriever.retrieve(c.question(), 10).stream().map(Doc::id).toList();
    for (int i = 0; i < ids.size(); i++) {
        if (c.goldChunkIds().contains(ids.get(i))) {
            if (i < 5) hit++;          // Hit@5
            mrr += 1.0 / (i + 1);
            break;
        }
    }
}
System.out.printf("Hit@5=%.2f MRR=%.2f%n", hit / evalSet.size(), mrr / evalSet.size());

public List<Document> search(UserPrincipal user, String query) {
    FilterExpressionBuilder b = new FilterExpressionBuilder();
    var filter = b.and(
        b.and(b.eq("tenant_id", user.tenantId()),            // 来自认证信息
              b.in("acl_groups", user.groups().toArray())),  // 用户所属组
        b.and(b.lte("security_level", user.clearance()),
              b.eq("status", "ACTIVE"))).build();            // 只检索生效版本
    return vectorStore.similaritySearch(SearchRequest.builder()
        .query(query).topK(8).filterExpression(filter).build());   // 预过滤
}

@KafkaListener(topics = "doc-changed")
public void onDocChanged(DocEvent e) {
    Doc doc = docRepo.latest(e.docId());
    if (doc == null || doc.deleted()) { vectorStore.delete(filter("doc_id", e.docId())); return; }
    if (indexState.version(e.docId()) >= doc.version()) return;      // 幂等，丢弃旧事件
    List<Document> chunks = splitter.split(doc).stream()
        .map(c -> c.withMeta(Map.of("doc_id", doc.id(), "version", doc.version(),
                                    "effective_to", doc.effectiveTo()))).toList();
    vectorStore.delete(filter("doc_id", doc.id()));                  // 先删旧块
    vectorStore.add(chunks);
    indexState.save(doc.id(), doc.version(), Instant.now());         // 记录同步延迟
}

List<Document> docs = reranker.rerank(q, hybridRetriever.search(q, 30)).stream()
        .filter(d -> d.getScore() >= 0.45).limit(5).toList();     // 阈值来自评测集
if (docs.isEmpty()) {
    String q2 = rewriter.rewrite(q);                                // 补救：改写后重试
    docs = reranker.rerank(q2, hybridRetriever.search(q2, 30)).stream()
            .filter(d -> d.getScore() >= 0.45).limit(5).toList();
}
if (docs.isEmpty()) {
    missLog.record(q);                                              // 用于补充知识库
    return "知识库中暂未找到相关内容，您可以换个问法，或转人工客服。";
}
return generate(q, docs, "仅根据资料回答；资料没有的内容请说明不知道，并标注引用编号。");

// 入库：父块存 KV，子块向量化并带 parent_id
for (Document section : splitBySection(doc)) {               // 父块：按章节
    String parentId = UUID.randomUUID().toString();
    parentStore.put(parentId, section.getText());
    List<Document> children = TokenTextSplitter.builder()
            .withChunkSize(200).build().apply(List.of(section));
    children.forEach(c -> {
        c.getMetadata().put("parent_id", parentId);
        c.getMetadata().put("title_path", section.getMetadata().get("title_path"));
    });
    vectorStore.add(children);
}

// 检索：子块召回 → 按父块去重 → 控制 token 预算
List<Document> hits = vectorStore.similaritySearch(
        SearchRequest.builder().query(question).topK(12).similarityThreshold(0.6).build());
LinkedHashSet<String> parentIds = hits.stream()
        .map(d -> (String) d.getMetadata().get("parent_id"))
        .collect(Collectors.toCollection(LinkedHashSet::new));   // 保留得分顺序
StringBuilder ctx = new StringBuilder();
for (String pid : parentIds) {
    String p = parentStore.get(pid);
    if (tokens(ctx) + tokens(p) > 6000) break;
    ctx.append(p).append("\n---\n");
}

// Parent-Child：子块入向量库，元数据记录父块 id
for (Doc parent : splitter.split(doc, 2000)) {
    parentStore.save(parent.id(), parent.text());
    for (Doc child : splitter.split(parent, 300))
        vectorStore.add(new Document(child.text(), Map.of("parentId", parent.id())));
}
// 检索子块 -> 去重父块 id -> 取父块作为上下文
List<String> ctx = vectorStore.similaritySearch(q).stream()
    .map(d -> (String) d.getMetadata().get("parentId")).distinct()
    .limit(3).map(parentStore::get).toList();
